shader:
// Spin - rotational whip. A rolls up around the centre (ease-in) while pushing in, the cut sits at the peak
// angular speed (progress 0.5), B carries on in the same direction, eases out of the push and settles upright.
// Motion blur = a virtual shutter in time: every tap re-evaluates angle + zoom at its own moment, so the smear
// follows the real angular speed (a fixed ~180 deg shutter: peak arc ~50 deg * blur, growing only gently with
// turns). Trailing comet weights put the bright head of every streak on the leading side, so the turn direction
// reads even in the smear; a small radial rush at the cut turns rings into a slight spiral.
// The cut: the still centre cuts hard (no double exposure where the image is sharp), toward the rim B takes over
// the late part of the shutter across ~3 frames, so the swap is buried in the swirl, the luma step is soft and
// odd / even frame counts behave the same. Mirror-filled corners on the slow, tilted frames get a longer shutter
// so reflections never read as doubled objects.

const int SPIN_TAPS = 47;          // + 1 extra fetch on the one tap split between A and B = 48 taps max
const float SPIN_N = 47.0;
const float SPIN_PI = 3.14159265;
const float SPIN_K = 3.5;          // speed-ramp exponent (higher = longer calm start, harder whip)
const float SPIN_ARC = 50.0;       // peak blur arc in degrees at blur = 1, turns = 360 (scales by turns^0.3)
const float SPIN_RUSH = 0.12;      // radial smear at the cut (spiral feel)
const float SPIN_EDGE = 3.5;       // extra smear where the frame is mirror-filled on the slow, tilted frames
const float SPIN_CUTW = 0.2;       // A/B blend window at the rim (progress units)

float spinEase(float t) {
    t = clamp(t, 0.0, 1.0);
    return t < 0.5 ? 0.5 * pow(max(2.0 * t, 1e-6), SPIN_K)
                   : 1.0 - 0.5 * pow(max(2.0 - 2.0 * t, 1e-6), SPIN_K);
}

float spinPush(float t) {          // smooth push-in bump, 1.0 at the cut
    t = clamp(t, 0.0, 1.0);
    float u = t < 0.5 ? 2.0 * t : 2.0 - 2.0 * t;
    return u * u * (3.0 - 2.0 * u);
}

float spinSpeed(float t) {          // normalised angular speed, 1.0 at the cut
    t = clamp(t, 0.0, 1.0);
    return pow(max(t < 0.5 ? 2.0 * t : 2.0 - 2.0 * t, 1e-6), SPIN_K - 1.0);
}

float spinHash(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

vec2 spinMap(vec2 uv, float ang, float z) {
    vec2 d = (uv - 0.5) * vec2(ratio, 1.0);
    float c = cos(ang);
    float s = sin(ang);
    d = vec2(c * d.x + s * d.y, -s * d.x + c * d.y) / z;
    return d / vec2(ratio, 1.0) + 0.5;
}

vec4 transition(vec2 uv) {
    float sgn = dir < 0.0 ? -1.0 : 1.0;
    float total = radians(turns) * sgn;
    float win = smoothstep(0.0, 0.2, progress) * (1.0 - smoothstep(0.8, 1.0, progress));
    float spd = spinSpeed(progress);
    bool sideB = progress >= 0.5;

    // shutter length in progress units
    float sh = radians(SPIN_ARC * blur * pow(turns / 360.0, 0.3)) / (SPIN_K * max(abs(total), 0.01)) * win;

    // mirror assist: where this pixel samples beyond the frame on a slow, tilted frame, lengthen the shutter
    float e0 = spinEase(progress);
    vec2 s0 = spinMap(uv, sideB ? total * (e0 - 1.0) : total * e0, 1.0 + zoom * spinPush(progress));
    vec2 ov = max(max(-s0, s0 - 1.0), vec2(0.0)) * vec2(ratio, 1.0);
    float slow = 1.0 - spd;
    sh *= 1.0 + SPIN_EDGE * slow * slow * smoothstep(0.0, 0.2, max(ov.x, ov.y));

    float rush = SPIN_RUSH * blur * spd * win;

    // share of B: hard cut in the still centre, soft blend toward the rim (hidden in the smear)
    float rr = length((uv - 0.5) * vec2(ratio, 1.0));
    float cw = SPIN_CUTW * smoothstep(0.02, 0.3, rr) + 0.002;
    float fB = clamp((progress - 0.497) / cw + 0.5, 0.0, 1.0);
    // B takes the last part of the shutter (a real cut mid-exposure); g maps the wanted B share to a tap share
    // through the comet weights, so the blend runs symmetric around the cut
    float g = fB + fB * (1.0 - fB) * (0.68 - 1.84 * fB);
    float bStart = SPIN_N * (1.0 - g);

    vec2 fc = floor(uv * resolution);
    // stratified jitter, stepped by the golden ratio per frame (no reseeding shimmer); 0.6 of a stratum hides
    // stepping while keeping grain low
    float jit = 0.5 + 0.6 * (fract(spinHash(fc) + 0.618034 * floor(time * 30.0 + 0.5)) - 0.5);

    vec4 acc = vec4(0.0);
    float wsum = 0.0;
    for (int i = 0; i < SPIN_TAPS; i++) {
        float fi = float(i);
        float uc = (fi + 0.5) / SPIN_N - 0.5;
        float uj = (fi + jit) / SPIN_N - 0.5;
        float tj = progress + uj * sh;
        float w = (0.15 + cos(SPIN_PI * uc)) * (0.6 + 0.8 * (uc + 0.5));   // trailing comet
        float e = spinEase(tj);
        float zb = 1.0 + zoom * spinPush(tj);
        float wB = clamp(fi + 1.0 - bStart, 0.0, 1.0);                     // boundary tap is split A/B
        if (wB < 1.0) {
            acc += getA(spinMap(uv, total * e, zb * (1.0 + rush * uj))) * (w * (1.0 - wB));
        }
        if (wB > 0.0) {
            acc += getB(spinMap(uv, total * (e - 1.0), zb * (1.0 - rush * uj))) * (w * wB);
        }
        wsum += w;
    }
    return acc / wsum;
}
